def difference_largest_smallest(numbers):
    if not numbers:
        return 0
    smallest = numbers[0]
    largest = numbers[0]
    for number in numbers:
        if number < smallest:
            smallest = number
        if number > largest:
            largest = number
    return largest - smallest
if __name__ == '__main__':
    sample_list = [15, 3, 8, 22, 1]
    result = difference_largest_smallest(sample_list)
    print(result)

def difference_largest_smallest(numbers):
    if not numbers:
        return 0
    largest = numbers[0]
    smallest = numbers[0]
    for number in numbers:
        if number > largest:
            largest = number
        if number < smallest:
            smallest = number
    return largest - smallest
if __name__ == '__main__':
    list1 = [1, 5, 2, 8, 3]
    print(difference_largest_smallest(list1))
    list2 = [10, 4, 7, 1, 9]
    print(difference_largest_smallest(list2))
    list3 = [5]
    print(difference_largest_smallest(list3))
    list4 = []
    print(difference_largest_smallest(list4))

def subtract_from_hundred(data):
    for item in data:
        yield 100 - item
if __name__ == '__main__':
    sample_list = [10, 20, 30, 40]
    results = list(subtract_from_hundred(sample_list))
    print(results)

