def compare_data(a, b):
    if type(a) != type(b):
        return a == b
    else:
        return a == b
if __name__ == '__main__':
    print(compare_data(10, 10))
    print(compare_data(10.0, 10))
    print(compare_data(10, 10.0))
    print(compare_data("hello", "hello"))
    print(compare_data("hello", "world"))
    print(compare_data(3.14, 3.1400000000000004))
    print(compare_data([1, 2], [1, 2]))

def compare_values(a, b):
    if type(a) != type(b):
        return False
    if isinstance(a, (int, float)):
        return a == b
    elif isinstance(a, str):
        return a == b
    else:
        return a == b
if __name__ == '__main__':
    print(f"Integers: {compare_values(10, 10)}")
    print(f"Integers unequal: {compare_values(10, 20)}")
    print(f"Floats equal: {compare_values(3.14, 3.14)}")
    print(f"Floats unequal: {compare_values(3.14, 3.15)}")
    print(f"Strings equal: {compare_values('hello', 'hello')}")
    print(f"Strings unequal: {compare_values('hello', 'world')}")
    print(f"Mixed types (int vs str): {compare_values(10, '10')}")
    print(f"Different types (list vs list): {compare_values([1], [1])}")

def compare_values(a, b):
    if type(a) is type(b):
        return a == b
    elif isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    elif isinstance(a, str) and isinstance(b, str):
        return a == b
    else:
        try:
            if a == b:
                return True
            else:
                return False
        except (TypeError, ValueError):
            return False
if __name__ == '__main__':
    print(f"Int comparison (5, 5): {compare_values(5, 5)}")
    print(f"Int comparison (5, 6): {compare_values(5, 6)}")
    print(f"Float comparison (3.14, 3.14): {compare_values(3.14, 3.14)}")
    print(f"Float comparison (3.14, 3.15): {compare_values(3.14, 3.15)}")
    print(f"String comparison ('hello', 'hello'): {compare_values('hello', 'hello')}")
    print(f"String comparison ('hello', 'world'): {compare_values('hello', 'world')}")
    print(f"Mixed comparison (10, 10.0): {compare_values(10, 10.0)}")
    print(f"Mixed comparison ('a', 1): {compare_values('a', 1)}")
    print(f"List comparison ([1], [1]): {compare_values([1], [1])}")
    print(f"None comparison (None, None): {compare_values(None, None)}")
    print(f"None comparison (None, []): {compare_values(None, [])}")

