    print("\n--- List 2 Statistics ---")
    print(f"Mean: {mean2:.4f}")
    print(f"Standard Deviation: {std_dev2:.4f}")
    if mean1 == mean2 and std_dev1 == std_dev2:
        print("\nComparison Result: The means and standard deviations of both lists are identical.")
    else:
        print("\nComparison Result: The statistics of the two lists are different.")
