def calculate_running_average(data, new_value):
    data.append(new_value)
    return sum(data) / len(data)
if __name__ == '__main__':
    sample_values = [10, 20, 30, 40, 50]
    sentinel = -1
    running_sum = 0
    step = 0
    for value in sample_values:
        if value == sentinel:
            break
        running_sum += value
        current_count = len(sample_values)
        average = running_sum / current_count
        print(f"Step {step + 1}: Input {value}, Running Average: {average:.2f}")
        step += 1

def calculate_running_average(data):
    return sum(data) / len(data) if data else 0
if __name__ == '__main__':
    sample_data = [10, 20, 30, 40, 50]
    sentinel = -1
    running_average = 0.0
    for number in sample_data:
        if number == sentinel:
            break
        running_average += number
        current_count = len(sample_data)
        if current_count > 0:
            running_average = running_average / current_count
        print(f"Input: {number}, Running Average: {running_average}")

def calculate_operations(num1, num2):
    try:
        n1 = float(num1)
        n2 = float(num2)
        sum_val = n1 + n2
        difference_val = n1 - n2
        product_val = n1 * n2
        if n2 != 0:
            quotient_val = n1 / n2
        else:
            quotient_val = "Undefined"
        return sum_val, difference_val, product_val, quotient_val
    except ValueError:
        return "Error: Invalid input. Please enter numeric values.", None, None, None
    except Exception as e:
        return f"An unexpected error occurred: {e}", None, None, None
if __name__ == '__main__':
    sample_num1 = "20"
    sample_num2 = "5"
    sum_result, diff_result, prod_result, quot_result = calculate_operations(sample_num1, sample_num2)
    print(f"Number 1: {sample_num1}")
    print(f"Number 2: {sample_num2}")
    if isinstance(sum_result, str):
        print(sum_result)
    else:
        print(f"Sum: {sum_result}")
        print(f"Difference: {diff_result}")
        print(f"Product: {prod_result}")
        print(f"Quotient: {quot_result}")

