import os
def load_item_names_from_file(filepath: str) -> dict[str, str]:
    item_names = {}
    try:
        with open(filepath, 'r') as f:
            for line in f:
                item_name = line.strip()
                if item_name:
                    item_names[item_name] = item_name
        return item_names
    except FileNotFoundError:
        return {}
    except Exception:
        return {}
