                    parts = code.split(',')
                    if len(parts) == 3:
                        r, g, b = map(int, parts)
                        name = rgb_to_name(r, g, b)
                        color_map[code] = name
                    else:
                        color_map[code] = "Invalid RGB Format"
                except ValueError:
                    color_map[code] = "Invalid RGB Values"
            else:
                color_map[code] = "Unknown Format"
        else:
            color_map[code] = name
    return color_map
