        print(f"'{name}': {hex_code}")
    print("\n--- Inverse Mapping Demonstration (Hex to RGB) ---")
    hex_samples = ["#FF0000", "#0000FF", "#808080"]
    for hex_val in hex_samples:
        rgb_value = hex_to_css(hex_val)
        print(f"'{hex_val}': {rgb_value}")

