            (10, 10, 10): "gray",
            (255, 255, 255): "White",
            (255, 255, 0): "LightYellow",
            (255, 165, 0): "LightSalmon",
            (255, 105, 180): "Pink",
        }
        return colors.get((r, g, b), f"RGB({r},{g},{b})")
    return "Invalid RGB values"
