import string
def build_dictionary(filepath):
    word_set = set()
    try:
        with open(filepath, 'r', encoding='utf-8') as file:
            text = file.read()
            for char in text:
                if char.isalpha():
                    word_set.add(char)
        return word_set
    except FileNotFoundError:
        return set()
    except Exception as e:
        return set()
if __name__ == '__main__':
    sample_filename = "sample_text.txt"
    sample_content = "This is a sample text for building a dictionary. Python is great."
    try:
        with open(sample_filename, 'w', encoding='utf-8') as f:
            f.write(sample_content)
    except IOError:
        pass
    dictionary = build_dictionary(sample_filename)
    print(dictionary)

import re
def build_dictionary(text):
    words = re.findall(r'\b\w+\b', text.lower())
    frequency_dict = {}
    for word in words:
        if word in frequency_dict:
            frequency_dict[word] += 1
        else:
            frequency_dict[word] = 1
    return frequency_dict
if __name__ == '__main__':
    sample_text = "The quick brown fox jumps over the lazy dog. Fox and dog are friends."
    result = build_dictionary(sample_text)
    print(result)

import re
def build_dictionary(text):
    words = re.findall(r'\b\w+\b', text.lower())
    frequency_dict = {}
    for word in words:
        frequency_dict[word] = frequency_dict.get(word, 0) + 1
    return frequency_dict
if __name__ == '__main__':
    sample_text = "The quick brown fox jumps over the lazy dog. Fox and dog are friends."
    result = build_dictionary(sample_text)
    print(result)

