import os
def create_dictionary_from_file(filepath):
    data = {}
    try:
        with open(filepath, 'r') as file:
            for line in file:
                parts = line.strip().split(':')
                if len(parts) == 2:
                    key = parts[0].strip()
                    value = parts[1].strip()
                    data[key] = value
        return data
    except FileNotFoundError:
        print(f"Error: The file '{filepath}' was not found.")
        return None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None
if __name__ == '__main__':
    sample_filename = "sample_data.txt"
    with open(sample_filename, 'w') as f:
        f.write("apple:red\n")
        f.write("banana:yellow\n")
        f.write("grape:purple\n")
    dictionary = create_dictionary_from_file(sample_filename)
    if dictionary is not None:
        print("Dictionary created successfully:")
        print(dictionary)
    else:
        print("Failed to create the dictionary.")
    non_existent_filename = "non_existent_file.txt"
    print("\nTesting with a non-existent file:")
    error_result = create_dictionary_from_file(non_existent_filename)
    if error_result is None:
        print("Gracefully handled FileNotFoundError.")

import string
def build_word_dictionary(filepath):
    word_set = set()
    try:
        with open(filepath, 'r', encoding='utf-8') as file:
            text = file.read()
            for char in text:
                if char.isalpha():
                    word_set.add(char)
        return word_set
    except FileNotFoundError:
        return set()
if __name__ == '__main__':
    sample_filename = "sample_text.txt"
    sample_content = "This is a sample text for building a dictionary. Words like python and script are important."
    with open(sample_filename, 'w', encoding='utf-8') as f:
        f.write(sample_content)
    dictionary = build_word_dictionary(sample_filename)
    print(dictionary)

