import string
def build_dictionary(filepath):
    word_set = set()
    try:
        with open(filepath, 'r', encoding='utf-8') as file:
            text = file.read()
            for char in text:
                if char.isalpha():
                    word_set.add(char)
        return word_set
    except FileNotFoundError:
        return set()
if __name__ == '__main__':
    sample_filename = "sample_text.txt"
    sample_content = "This is a sample text for building a dictionary. Words like python and script are important."
    with open(sample_filename, 'w', encoding='utf-8') as f:
        f.write(sample_content)
    dictionary = build_dictionary(sample_filename)
    print(dictionary)

def build_dictionary(text):
    words = text.lower()
    cleaned_words = []
    for char in words:
        if 'a' <= char <= 'z' or char == ' ':
            cleaned_words.append(char)
    words_list = []
    current_word = ""
    for char in text:
        if 'a' <= char <= 'z' or char == ' ':
            current_word += char
        else:
            if current_word:
                words_list.append(current_word)
                current_word = ""
    if current_word:
        words_list.append(current_word)
    unique_words = set()
    for word in words_list:
        if word:
            unique_words.add(word)
    return unique_words
if __name__ == '__main__':
    sample_text1 = "Hello world! This is a test sentence, and it contains punctuation."
    sample_text2 = "Python programming is fun. Programming is powerful."
    sample_text3 = "  Multiple   spaces and  punctuation? Yes!"
    dict1 = build_dictionary(sample_text1)
    print(f"Dictionary for '{sample_text1}': {dict1}")
    dict2 = build_dictionary(sample_text2)
    print(f"Dictionary for '{sample_text2}': {dict2}")
    dict3 = build_dictionary(sample_text3)
    print(f"Dictionary for '{sample_text3}': {dict3}")

